/**
 * Shared data layer for the dev-mode database admin UI.
 *
 * Both sibling surfaces — TableEditor (`TableEditor.tsx`) and SqlEditor
 * (`SqlEditor.tsx`) — import their data access from this module so the request
 * shapes, error handling, and agent-write auto-refetch behavior stay
 * consistent.
 *
 * Every read hook folds the `["db-admin", "action"]` change counters into its
 * React Query key, so when the agent writes to the database (via an action that
 * emits a change event) the open table or query result refetches immediately —
 * the same "agent writes show up instantly" primitive templates use.
 */
import { useQuery, keepPreviousData, } from "@tanstack/react-query";
import { agentNativePath } from "../api-path.js";
import { getBrowserTabId } from "../browser-tab-id.js";
import { useChangeVersions } from "../use-change-version.js";
// ─── Base path ───────────────────────────────────────────────────────────
export const dbAdminBasePath = agentNativePath("/_agent-native/db-admin");
function requestBasePath(config) {
    return (config?.basePath ?? dbAdminBasePath).replace(/\/+$/, "");
}
function requestScopeKey(config) {
    return config?.scopeKey ?? requestBasePath(config);
}
// ─── Tab id (request source) ───────────────────────────────────────────────
/**
 * Stable per-tab identifier sent as `x-request-source` so the backend can
 * attribute changes to this tab and skip echoing them back to the originator.
 */
function getRequestSource() {
    if (typeof window === "undefined")
        return undefined;
    return getBrowserTabId();
}
function baseHeaders(extra) {
    const headers = { ...extra };
    const source = getRequestSource();
    if (source)
        headers["x-request-source"] = source;
    return headers;
}
async function parseEnvelope(res) {
    let json = null;
    try {
        json = (await res.json());
    }
    catch {
        json = null;
    }
    if (!res.ok || (json && json.ok === false)) {
        const message = (json && json.error) || `Request failed (HTTP ${res.status})`;
        const err = new Error(message);
        if (json && json.needsConfirm) {
            err.needsConfirm = true;
        }
        throw err;
    }
    if (!json) {
        throw new Error(`Empty response (HTTP ${res.status})`);
    }
    return json;
}
export async function dbAdminGet(subpath, config) {
    const res = await fetch(`${requestBasePath(config)}${subpath}`, {
        method: "GET",
        credentials: "include",
        headers: baseHeaders(),
    });
    return parseEnvelope(res);
}
export async function dbAdminPost(subpath, body, config) {
    const res = await fetch(`${requestBasePath(config)}${subpath}`, {
        method: "POST",
        credentials: "include",
        headers: baseHeaders({ "Content-Type": "application/json" }),
        body: JSON.stringify(body),
    });
    return parseEnvelope(res);
}
function toState(query) {
    return {
        data: query.data,
        isLoading: query.isLoading,
        error: query.error ?? null,
        refetch: () => {
            void query.refetch();
        },
    };
}
export function useOverview(config) {
    const version = useChangeVersions([
        "db-admin",
        "analytics-db-admin",
        "action",
    ]);
    const query = useQuery({
        queryKey: ["db-admin", requestScopeKey(config), "overview", version],
        queryFn: async () => {
            const res = await dbAdminGet("/overview", config);
            return { tables: res.tables };
        },
        placeholderData: keepPreviousData,
        staleTime: 2000,
    });
    return toState(query);
}
export function useTableSchema(table, config) {
    const version = useChangeVersions([
        "db-admin",
        "analytics-db-admin",
        "action",
    ]);
    const query = useQuery({
        queryKey: ["db-admin", requestScopeKey(config), "schema", table, version],
        enabled: !!table,
        queryFn: async () => {
            const res = await dbAdminGet(`/table/${encodeURIComponent(table)}/schema`, config);
            return res.table;
        },
        placeholderData: keepPreviousData,
        staleTime: 2000,
    });
    return toState(query);
}
// ─── Table rows ────────────────────────────────────────────────────────────
export function useTableRows(table, req, config) {
    const version = useChangeVersions([
        "db-admin",
        "analytics-db-admin",
        "action",
    ]);
    const query = useQuery({
        queryKey: [
            "db-admin",
            requestScopeKey(config),
            "rows",
            table,
            req,
            version,
        ],
        enabled: !!table,
        queryFn: () => dbAdminPost(`/table/${encodeURIComponent(table)}/rows`, req, config),
        placeholderData: keepPreviousData,
        staleTime: 2000,
    });
    return toState(query);
}
// ─── Mutations ─────────────────────────────────────────────────────────────
export async function mutateTable(table, mutation, config) {
    return dbAdminPost(`/table/${encodeURIComponent(table)}/mutate`, mutation, config);
}
export async function runQuery(sql, params, confirmDestructive, config) {
    return dbAdminPost("/query", {
        sql,
        params,
        confirmDestructive,
    }, config);
}
